const book34Deepening: Partial<Record<number, { title: string; body: string }>> = {
  2: {
    title: "Praise attaches to a way of carrying poverty",
    body: "The reports cannot mean that every lack is good. Ghazali has just told apart detachment, contentment, satisfaction, grasping and need, all within the same outward situation. So the reports have to be read through the state of the heart. They praise fewer distractions, freedom from grasping, patience, and turning toward God. Poverty can remove one area of temptation. But it does not supply any of those responses by itself, and it does not excuse ignoring a need that should be met.",
  },
  3: {
    title: "Why inward state changes the meaning of lack",
    body: "Two people may have equally little and yet be moving in opposite directions. One is freed from chasing what he lacks; another is taken up with it all day. A third may be in real need and obliged to seek help. So the praise follows a truthful relationship to the situation, not the situation by itself. This protects the person in need from being blamed for his need. It also stops the grasping person from claiming a virtue just because his hands are empty.",
  },
  4: {
    title: "What the general preference is comparing",
    body: "The preference for poverty is about tendencies. It does not claim that every poor person is better than every rich person. Wealth usually brings more things to get, manage, fear losing, and answer for. Poverty can shrink that field. But the actual state still matters. A resentful or grasping poverty may be worse for the soul than wealth held with gratitude, spent rightly, and loosely held. That is why the matched comparison has to follow.",
  },
  5: {
    title: "Why gratitude and satisfaction cannot be compared by labels",
    body: "The satisfied poor person has fewer means and bears their absence well. The grateful rich person has more means, and he recognises where they come from, holds back, and puts them to use. Each state has a real excellence and its own particular risk. Ghazali's method asks what the condition is doing to the heart and what duties it creates. He does not let the attractive name of either state decide the case before its real qualities are examined.",
  },
  6: {
    title: "Conduct makes the claimed state testable",
    body: "A person may call himself content while he keeps showing off how little he has, resenting those with more, or lowering himself before people who might give. The manners expose these contradictions. Holding back complaint, refusing to put on a spiritual show, keeping one's dignity, and meeting one's duties all test the state. They show whether it governs conduct when lack starts to hurt. The point is not to hide real need. It is to stop poverty becoming either a public identity that seeks attention or a private grudge that eats up the heart.",
  },
  7: {
    title: "Acceptance and refusal each need a reason",
    body: "A gift that was not asked for does not bring the humiliation or pressure of asking. But it still calls for judgement. The receiver looks at whether the gift is lawful and what the giver intends. He asks whether accepting creates an unhealthy claim on him, and what accepting or refusing will do to his heart. Refusing is not automatically purer. It can be a display of detachment, it can hurt the giver, or it can turn away provision that should be used. The decision follows truth and consequences, not one fixed pose.",
  },
  8: {
    title: "Necessity changes the act without removing its cost",
    body: "Asking makes the asker depend on another person's answer, and it can be a burden on the person asked. That is why Ghazali treats needless asking severely. Real necessity changes the case. Keeping oneself alive, keeping the body working, supporting dependents, or meeting an obligation may require help. Even then, the request should be truthful and in proportion. It should go where help can responsibly be given. Permission answers the need; it does not turn repeated asking into an identity or a habit.",
  },
  9: {
    title: "Sufficiency is a relation, not a universal number",
    body: "The same amount can be enough for one person and too little for another. Needs, dependents, health, prices and time all differ. So Ghazali asks what kind of provision is needed, how much of it meets the need, and for how long. This avoids both false precision and people simply vouching for themselves without limit. There is still a line. But it must be justified by the person's actual responsibilities. It cannot be borrowed from someone else's situation, or stretched to cover every possible future worry.",
  },
  10: {
    title: "The giver also needs a diagnosis",
    body: "Sorting askers keeps generosity from becoming careless or scornful. A person in urgent need, someone unable to earn, and someone trained into asking as a habit are not the same case, even if their words sound alike. The giver must pay attention to evidence, urgency, dignity and the likely result. He must do this without claiming to see the hidden heart. The aim is help matched to the real need, not a reward for a performance or a punishment based on suspicion.",
  },
  12: {
    title: "Detachment names an exchange of value",
    body: "Leaving something is only half the movement. Ghazali's definition asks what is preferred instead. Going without, with no better thing in view, may be force, inability or loss, not detachment. The praise is for turning from a smaller share toward what is judged better and more lasting. This keeps the lawful use of necessary things. It exposes the inner mistake of treating them as final. It also stops going without from becoming the new thing to be proud of.",
  },
  14: {
    title: "The real object may be less visible than the possession",
    body: "What is left is not simply the physical object. A person may give up owning something and still keep his longing for it or his comparisons. He may keep his pride in giving it up, or his concern with how the sacrifice looks. On the other hand, something needed for a duty may stay in the hand without ruling the heart. So naming the object moves the question from a list of belongings to a relationship. Which share, pleasure, status or claim is being preferred? And what higher good is meant to replace it?",
  },
  15: {
    title: "A person can be detached in one field and attached in another",
    body: "Sorting by object replaces a flattering overall label with a map you can use. Someone may be free about food but ruled by clothing. He may not care about possessions but hunger for reputation. He may be modest in housing but attached to authority. These are not contradictions once detachment is seen as a relationship lived out in particular areas. The sorting shows where freedom is real, where necessity remains, and where an unexamined share still carries the heart.",
  },
  17: {
    title: "Concrete measures turn aspiration into examination",
    body: "Food, clothing, housing and furnishings each serve different needs. So each raises different questions about amount, quality, how long it lasts, and what it is for. The examples do not set one lifestyle for every reader for all time. They show how to reason from need and use to a limit. Without that reasoning, a person can call any comfort necessary. Or he can copy someone else's strict living while ignoring health, dependents, climate, work, and the duties his own situation creates.",
  },
};

export const book34Chapters: Chapter[] = book34Base.map((chapter) => {
  const extra = book34Deepening[chapter.id];
  if (!extra || !chapter.deep) return chapter;
  return { ...chapter, deep: { ...chapter.deep, closeReading: [...(chapter.deep.closeReading ?? []), extra] } };
});

